import { useState } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";

function App() {
  const [primeResult, setPrimeResult] = useState(null);
  const [q1Result, setQ1Result] = useState(null);
  const [number, setNumber] = useState("");

  // Call backend to check primality
  const checkPrime = async () => {
    const res = await fetch(`http://localhost:8000/api/testprime?n=${number}`);
    const data = await res.json();
    setPrimeResult(data);
  };

  // Call backend to run Q1
  const runQ1 = async () => {
    const res = await fetch("http://localhost:8000/api/question1");
    const data = await res.json();
    setQ1Result(data.result);
  };

  return (
    <div className="min-h-screen bg-gray-100 flex flex-col items-center p-6">
      <h1 className="text-3xl font-bold mb-6">Prime Number Playground</h1>

      {/* Prime tester card */}
      <Card className="w-full max-w-md mb-6 shadow-lg">
        <CardContent className="p-4 flex flex-col gap-3">
          <h2 className="text-xl font-semibold">Prime Tester</h2>
          <input
            type="text"
            placeholder="Enter a number"
            value={number}
            onChange={(e) => setNumber(e.target.value)}
            className="border p-2 rounded"
          />
          <Button onClick={checkPrime}>Check</Button>
          {primeResult && (
            <p className="mt-2">
              {primeResult.error
                ? primeResult.error
                : primeResult.prime
                ? "✅ Prime"
                : "❌ Not Prime"}
            </p>
          )}
        </CardContent>
      </Card>

      {/* Question 1 card */}
      <Card className="w-full max-w-md shadow-lg">
        <CardContent className="p-4 flex flex-col gap-3">
          <h2 className="text-xl font-semibold">Question 1</h2>
          <p>
            Find palindromic number formed by 1..i..1 (between 2600–3000) that is
            prime.
          </p>
          <Button onClick={runQ1}>Run Question 1</Button>
          {q1Result && <p className="mt-2">{q1Result}</p>}
        </CardContent>
      </Card>
    </div>
  );
}

export default App;
